 class Task implements Callable<String> {
    int n;
    public Task(int n) {
        this.n = n;
    }

    @Override
    public String call() throws Exception {
        if (n == 0) {
            return "INSOMNIA";
        }
        boolean[] seen = new boolean[10];
        long x = n;
        while(true) {
            String s = String.valueOf(x);
            for(int i=0;i<s.length();i++) {
                seen[s.charAt(i) - '0'] = true;
            }
            boolean flag = true;
            for(boolean f: seen) {
                if (!f) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                break;
            }
            x += n;
        }
        return String.valueOf(x);
    }

 }

