      class Composite implements Comparable<Composite>{
            int v;
            int idx;

            public int compareTo(Composite X){
                if (v!=X.v)
                    return v-X.v;
                return idx-X.idx;
            }

            public Composite(int v, int idx) {
                super();
                this.v = v;
                this.idx = idx;
            }



        }



      int getPath(int[][] mat,int B){
          int[] num=new int[B];
          num[0]=1;
          for (int i=1;i<B;i++)
              for (int j=0;j<i;j++){
                  if (mat[j][i]==1){
                      num[i]+=num[j];
                  }
              }
          return num[B-1];
      }

     String solveBourrin(int B,int M){
         int max=(B*B-B)/2;
         int LX=1<<max;
         log("max:"+max);
         for (int u=0;u<LX;u++){
             int i=0;
             int j=1;
             int c=0;
             int[][] map=new int[B][B];
             while (c<max){
                 int msk=1<<c;
                 if ((u&msk)!=0){
                     map[i][j]=1;
                 }
                 j++;
                 if (j==B){
                     i++;
                     j=i+1;
                 }
                 c++;
             }
             int x=getPath(map,B);
             if (x==M){
                 String rs="POSSIBLE\n";
                 for (int e=0;e<B;e++) {
                     for (int f=0;f<B;f++){
                         rs+=map[e][f];
                     }
                     rs+="\n";
                 }
                 return rs;
             }
         }
         return "IMPOSSIBLE\n";
     }

