    int map(int x,int y){
        return map[x-1][y-1];
    }

    int[][] map={{1,I,J,K},{I,-1,K,-J},{J,-K,-1,I},{K,J,-I,-1}};

    String YES="YES";
    String NO="NO";


    String solveBourrin(String s,long X,int L){

        int x=s.charAt(0)-'i'+I;
        int mult=1;
        int step=0;
        int sign=1;
        for (int i=0;i<L*X;i++){
            int y=(s.charAt(i%L)-'i')+I;
            mult=map(mult,y);
            if (mult<0){
                mult*=-1;
                sign*=-1;
            }
            if (step==0 && mult==I){
                step++;
                mult=1;
            } else {
                if (step==1 && mult==J){
                    step++;
                    mult=1;
                }
            }
        }
        if (step==2 && mult==K && sign==1)
            return YES;
        else
            return NO;

    }

