             double D = getInt();
             int N = getInt();
             double minTime = 0;
             for (int i = 0; i < N; i++) {
                 double position = getInt();
                 double speed = getInt();

                 double time = (D - position) / speed;
                 minTime = Math.max(minTime, time);
             }
             double speed = D / minTime;
             return String.format(Locale.ENGLISH, "%.6f", speed);
         }
     }
