                 K -= num;
                 addToMap(size / 2, num, map);
                 addToMap((size - 1) / 2, num, map);
             }
         }
     }

     void addToMap(long key, long val, TreeMap<Long, Long> map) {
         if (map.containsKey(key))
             map.put(key, map.get(key) + val);
         else
             map.put(key, val);
     }
 }
