                for (int i = 0; i < n; i++) {
                    res1 += p[i] / d - 1;
                    if (p[i] % d != 0)
                        res1++;
                }

                if (res1 < res) {
                    res = res1;
                }
            }
            out.println("Case #" + test + ": " + res);
        }
    }
