         long[] finv = new long[n + 1];
         f[0] = 1;
         finv[0] = 1;
         for (int i = 1; i <= n; i++) {
             f[i] = (f[i - 1] * i) % MOD;
             finv[i] = BigInteger.valueOf(f[i]).modInverse(BigInteger.valueOf(MOD)).longValue();
         }
         long[] p = new long[n + 1];
         p[0] = 1;
         p[1] = 0;
         for (int i = 2; i <= n; i++) {
             p[i] = (p[i - 1] + p[i - 2]) * (i - 1) % MOD;
