         long res = 0;
         for (int i = x; i <= n; i++) {
             long q = p[n - i] * finv[i];
             q %= MOD;
             q *= finv[n - i];
             q %= MOD;
             q *= f[n];
             q %= MOD;
             q *= f[n];
             q %= MOD;

