         int[] t = new int[n];
         int best = Integer.MAX_VALUE;
         for (int m = 0; m < (1 << n); m++) {
             for (int i = 0; i < n; i++) {
                 t[i] = (m >> i) & 1;
             }
             boolean[] z = new boolean[2 * n];
