    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int res = Integer.MAX_VALUE;
            int D = in.nextInt();
            int[] P = in.nextIntArray(D);
            Arrays.sort(P);

            for (int max = 1; max <= 1000; max++) {
                int cnt = 0;
                for (int i = 0; i < D; i++) {
                    cnt += (P[i] - 1) / max;
