public class C {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    long INF = (long) 1e16;

    class State implements Comparable<State> {
        int u;
        double t;

        State(int u, double dist) {
            this.u = u;
            this.t = dist;
        }

        public int compareTo(State s) {
            return Double.compare(t, s.t);
        }

        public String toString() {
            return "(" + u + ", " + t + ")";
        }
    }

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int N = in.nextInt(), Q = in.nextInt();
            long[] E = new long[N];
            long[] S = new long[N];
            for (int i = 0; i < N; i++) {
                E[i] = in.nextLong();
                S[i] = in.nextLong();
            }
            long[][] D = new long[N][N];
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    int d = in.nextInt();
                    if (d == -1) 
                        D[i][j] = INF;
                    else 
                        D[i][j] = d;
                }
            }

            for (int k = 0; k < N; k++) for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) {
                if (i == j || j == k || k == i) continue;
                D[i][j] = Math.min(D[i][j], D[i][k] + D[k][j]);
            }

            StringBuilder res = new StringBuilder();
            double[] minTime = new double[N];
            PriorityQueue<State> pq = new PriorityQueue<>();

            for (int q = 0; q < Q; q++) {
                int U = in.nextInt() - 1, V = in.nextInt() - 1;
                Arrays.fill(minTime, INF);
                minTime[U] = 0;
                pq.clear();
                pq.add(new State(U, 0));

                while (!pq.isEmpty()) {
                    State st = pq.poll();
                    if (st.t > minTime[st.u]) continue;

                    for (int to = 0; to < N; to++) {
                        if (D[st.u][to] == INF) continue;
                        if (D[st.u][to] > E[st.u]) continue;

                        double nextTime = st.t + (double)D[st.u][to] / S[st.u];
                        if (nextTime < minTime[to]) {
                            minTime[to] = nextTime;
                            pq.add(new State(to, nextTime));
                        }
                    }
                }
                res.append(minTime[V]);
                if (q != Q - 1) res.append(" ");
            }

            out.println("Case #" + caseN + ": " + res.toString());
        }
        out.close();
    }

    public static void main(String[] args) {
        new C().run();
    }

