public class A {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    char convert(int c) {
        return (char)(c + 'A');
    }

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            List<String> res = new ArrayList<String>();
            int n = in.nextInt();
            int[] p = in.nextIntArray(n);

            int rest = 0;
            PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> (p[b] - p[a]));
            for (int i = 0; i < n; i++) {
                pq.add(i);
                rest += p[i];
            }

            if (rest % 2 != 0) {
                int next = pq.poll();
                res.add(convert(next) + "");
                p[next]--;
                pq.add(next);
                rest--;
            }
            while (rest > 0) {
                String s = "";
                for (int i = 0; i < 2; i++) {
                    int next = pq.poll();
                    s += convert(next);
                    p[next]--;
                    pq.add(next);
                }
                res.add(s);
                rest -= 2;
            }

            StringBuilder ans = new StringBuilder();
            for (String s : res) {
                ans.append(s + " ");
            }
            out.println("Case #" + caseN + ": " + ans.toString());
        }
        out.close();
    }

