                 id[i] = in.nextInt() - 1;
             }
             int[] sumPos = new int[n];
             int[] cnt = new int[c];
             for (int i = 0; i < m; i++) {
                 sumPos[p[i]]++;
                 cnt[id[i]]++;
             }
             int res = 0;
             for (int z : cnt) {
                 res = Math.max(res, z);
             }
             int totalTickets = 0;
             for (int i = 0; i < n; i++) {
