    }

    int intLine(){
        return Integer.parseInt(scan.nextLine());
    }

    class ch{
        ch(char a, int b){c=a;x=b;}
        char c;int x;
        @Override
        public String toString() {

            return c+" "+x;
        }
    }

    String doit(ch a, ch b, ch c){
        StringBuffer sb = new StringBuffer();
        ch curr;
        ch start;
        if(a.x>0){
            sb.append(a.c);a.x--;start=a;
        }else if(b.x>0){
            sb.append(b.c);b.x--;start=b;
        }else{
            sb.append(c.c);c.x--;start=c;
        }
        curr=start;
        while(a.x+b.x+c.x>0){
            ch o1;ch o2;
            if(a==curr){
                o1 = b;o2=c;
            }else if(b==curr){
                o1=a;o2=c;
            }else{
                o1=a;o2=b;
            }
            if(o1.x+o2.x==0)return null;
            if(o1.x>o2.x){
                curr = o1;
            } else if(o2.x>o1.x){
                curr = o2;
            }else {
                if(o1==start)curr=o1;
                else curr=o2;
            }
            sb.append(curr.c);curr.x--;
        }
        if(curr==start)return null;
        return sb.toString();
    }

    public String solve() {
        int n = scan.nextInt();
        int r = scan.nextInt();
        int o = scan.nextInt();
        int y = scan.nextInt();
        int g = scan.nextInt();
        int b = scan.nextInt();
        int v = scan.nextInt();
