                    if(g[i][j] != -1 && g[j][i] == -1){
                        ans[g[i][j]] = bal[i][j];
                    }else if(g[i][j] == -1 && g[j][i] != -1){
                        ans[g[j][i]] = bal[j][i];
                    }else{
                        if(bal[i][j] + 1 != 0 && bal[i][j] + 1 <= n*n){
                            ans[g[i][j]] = bal[i][j] + 1;
                            ans[g[j][i]] = 1;
                        }else if(bal[i][j] - 1 != 0 && bal[i][j] - 1 >= -n*n){
                            ans[g[i][j]] = bal[i][j] - 1;
                            ans[g[j][i]] = -1;
                        }else{
                            throw new RuntimeException();
                        }
                    }
                }
            }
