import static java.lang.Math.min;

 public class ProblemC4 {
     BufferedReader rd;

     ProblemC4() throws IOException {
         rd = new BufferedReader(new InputStreamReader(System.in));
         compute();
     }

     private void compute() throws IOException {
         int n = pint();
         for(int i=0;i<n;i++) {
             out("Case #" + (i + 1) + ": " + solve());
         }
     }

     private String solve() throws IOException {
         long[] a = longarr();
         long n = a[0];
         long k = a[1];
         long[] res = solve(n, k);
         return res[0] + " " + res[1];
     }

     private long[] solve(long n, long k) {
         NavigableMap<Long, Long> g = new TreeMap<>();
         g.put(n, 1L);
         long steps = 0;
         k--;
         while(steps < k && !g.isEmpty()) {
             Map.Entry<Long, Long> e = g.lastEntry();
             g.remove(e.getKey());
             long z = e.getKey();
             long v = e.getValue();
             long c = min(v, k-steps);
             if(c < v) {
                 add(g, z, v-c);
             }
             if(z > 1) {
                 if(z % 2 == 0) {
                     add(g, z/2, c);
                     if(z/2 - 1 > 0) {
                         add(g, z / 2 - 1, c);
                     }
                 } else {
                     add(g, z/2, c*2);
                 }
             }
             steps += c;
         }
         if(g.isEmpty()) {
             return new long[2];
         }
         long last = g.lastKey();
         long y = last / 2;
         if(last % 2 == 0) {
             return new long[] { y, y - 1 };
         } else {
             return new long[] { y, y };
         }
     }

     private void add(Map<Long, Long> m, long key, long diff) {
         m.put(key, m.getOrDefault(key, 0L) + diff);
     }

