package con2017.con2017R1A;












 public class A {

   static final String islarge = "-large";
   private static final String fileLoc = "src/con2017/con2017R1A/files/";
   private static final String fileName = fileLoc + A.class.getSimpleName().toLowerCase();
   private static final String inputFileName = fileName + ".in";
   private static final String outputFileName = fileName + ".out";
   private static InputReader in;
   private static OutputWriter out;

   private void solve() {
     int R = in.readInt(), C = in.readInt();
     char[][] grid = new char[R][C];
     for (int r = 0; r < R; r++) {
       String s = in.readLine();
       for (int c = 0; c < C; c++) {
         grid[r][c] = s.charAt(c);
         if (grid[r][c] == '?') {
           if (c > 0 && grid[r][c - 1] != '?') {
             grid[r][c] = grid[r][c - 1];
           }
         } else if (c > 0 && grid[r][c - 1] == '?') {
           for (int c1 = c - 1; c1 >= 0; c1--) {
             grid[r][c1] = grid[r][c];
           }
         }
       }
     }

     for (int r = 1; r < R; r++) {
       if (grid[r - 1][0] == '?' && grid[r][0] != '?') {
         for (int c = 0; c < C; c++) {
           grid[r - 1][c] = grid[r][c];
         }
       } else if (grid[r - 1][0] != '?' && grid[r][0] == '?') {
         for (int c = 0; c < C; c++) {
           grid[r][c] = grid[r - 1][c];
         }
       }
     }

     for (int r = R - 1; r > 0; r--) {
       if (grid[r][0] == '?' && grid[r - 1][0] != '?') {
         for (int c = 0; c < C; c++) {
           grid[r][c] = grid[r - 1][c];
         }
       } else if (grid[r][0] != '?' && grid[r - 1][0] == '?') {
         for (int c = 0; c < C; c++) {
           grid[r - 1][c] = grid[r][c];
         }
       }
     }
     for (int r = 0; r < R; r++) {
       for (int c = 0; c < C; c++) {
         out.print(grid[r][c]);
       }
       out.printLine();
     }
   }

   public static void main(String[] args) throws IOException {
     long start = System.currentTimeMillis();
     in = new InputReader(new FileInputStream(inputFileName));
     out = new OutputWriter(new FileOutputStream(outputFileName));
     int tests = in.readInt();
     for (int t = 1; t <= tests; t++) {
       out.printLine("Case #" + t + ":");
       new A().solve();
       System.out.println("Case #" + t + ": solved");
     }
     out.close();
     long stop = System.currentTimeMillis();
     System.out.println(stop - start + " ms");
   }


