 public class C {

    private static final String islarge = "-large";
    private static final String fileLoc = "src/con2016/con2016Q/files/";
    private static final String fileName = fileLoc+C.class.getSimpleName().toLowerCase()+islarge;
    private static final String inputFileName = fileName + ".in";
    private static final String outputFileName = fileName + ".out";
    private static InputReader in;
    private static OutputWriter out;


    static final int[] primes = new int[]{2,3,5,7,11,13};
    private void solve() {
        int N = in.readInt(), 
            J = in.readInt();
        long a = (1L<<(N-1))+1;
        int[] res = new int[11];
        while(J > 0){
            String b2Rep = b2Rep(a);
            System.err.println(">> "+a+" -- "+b2Rep);
            for(int base=2;base<=10;base++){
                BigInteger b = new BigInteger(b2Rep, base);
                res[base] = -1;
                for(int p : primes){
                    if(b.mod(BigInteger.valueOf(p)).equals(BigInteger.ZERO)){
                        res[base]=p;break;
                    }
                }
                if(res[base]==-1)break;
            }
            if(res[10] > 1){
                J--;
                System.err.println(">> "+b2Rep);
                out.print(b2Rep);
                for(int base=2;base<=10;base++){
                    out.print(" "+res[base]);
                }
                out.printLine();
                res[10]=-1;
            }
            a+=2;
        }
    }

    static String b2Rep(long num){
        String s = "";
        while(num > 0){
            s = ((num&1)==1 ? 1 : 0) + s;
            num >>= 1;
        }
        return s;
    }

    static long convBase(long num, long base){
        long res = 0;
        long mul = 1;
        while(num > 0){
            if(mul < 0)throw new RuntimeException("afafa");
            if((num&1)==1){
                res += mul;             
            }
            num >>= 1;
            mul *= base;
        }
        return res;
    }

