         }
         out.flush();
     }

     private static int solve(char[] c) {
         int n = c.length;
         int sum = 0;
         int invite = 0;
         for (int i = 0 ; i < n ; i++) {
             if (sum < i) {
                 invite += i - sum;
                 sum = i;
             }
             sum += c[i] - '0';
         }
         return invite;
     }

     static void debug(Object... o) {
         System.err.println(Arrays.deepToString(o));
     }
 }



