    static
    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        int h, w, n;
        long d;
        long[][] map;
        public void readInput(final IOFast io) throws IOException {
            h = io.nextInt();
            w = io.nextInt();
            n = io.nextInt();
            d = io.nextInt();
            map = new long[h][w];
            for (int i = 0; i < n; i++) {
                int y = io.nextInt() - 1;
                int x = io.nextInt() - 1;
                int v = io.nextInt();
                map[y][x] = v;
            }
        }

        @Override
        public void run() {
            min = new long[h][w];
            max = new long[h][w];
            for (int y = 0; y < h; y++) {
                Arrays.fill(min[y], Long.MIN_VALUE);
                Arrays.fill(max[y], Long.MAX_VALUE);
            }
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    if (map[y][x] > 0) fill(x, y, map[y][x]);
                }
            }
            long sum = 0;
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    if (min[y][x] > max[y][x]) {
                        out.println("IMPOSSIBLE");
                        return;
                    }
                    sum += max[y][x];
                }
            }
            out.println(sum % mod);
        }

        long[][] min;
        long[][] max;
        void fill(int x0, int y0, long v) {
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    long c = (Math.abs(x-x0)+Math.abs(y-y0))*d;
                    min[y][x] = Math.max(min[y][x], v - c);
                    max[y][x] = Math.min(max[y][x], v + c);
                }
            }
        }


