    static class Dinic {
        final int INF = 1 << 29;


        AdjListGraph g;
        int[] level, iter, q;
        List<int[]> es = new ArrayList<>();

        void bfs(int s) {
            for (int i = 0; i < level.length; i++) level[i] = -1;

            int qs = 0, qt = 0;
            level[s] = 0;
            q[qt++] =s;
            while (qs != qt) {
                int v = q[qs++];
                for(int e = g.head[v]; e != -1; e = g.next[e]) {
                    final int t = g.to[e];
                    if (g.cap[e] > 0 && level[t] < 0) {
                        level[t] = level[v] + 1;
                        q[qt++] = t;
                    }
                }
            }
        }

        int dfs(int v, int t, int f) {
            if (v == t) return f;
            for (int i = iter[v]; i != -1; i = iter[v] = g.next[i]) {
                if (g.cap[i] > 0 && level[v] < level[g.to[i]]) {
                    int d = dfs(g.to[i], t, Math.min(f, g.cap[i]));
                    if (d > 0) {
                        g.cap[i] -= d;
                        g.cap[g.rev[i]] += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        public void AddEdge(int from, int to, int cap) {
            es.add(new int[]{from, to, cap, });


        }

        private void build() {
            if(g == null) {
                g = new AdjListGraph(level.length, 2 * es.size() * 2);
                for(int[] e : es) {
                    g.addEdge(e[0], e[1], e[2], g.m + 1);
                    g.addEdge(e[1], e[0], 0, g.m - 1);
                }
            }
        }

        public int MaxFlow(int s, int t) {
            build();
            int flow = 0;
            for (; ; ) {
                bfs(s);
                if (level[t] < 0) return flow;
                for (int i = 0; i < iter.length; i++) iter[i] = g.head[i];
                for (int f = 0; (f = dfs(s, t, INF)) > 0; )
                    flow += f;
            }
        }

        public int BipartiteMatching(int s, int t) {
            return MaxFlow(s, t);
        }

        void clear() {
            g.clear();
        }

        void clear(int n) {
            g.clear(n);
        }

        public Dinic(int size) {
            level = new int[size];
            iter = new int[size];
            q = new int[size];
        }

        static class AdjListGraph {
            int m;
            int[] head, next, to, rev;
            int[] cap;

            public AdjListGraph(int V, int E) {
                head = new int[V];
                next = new int[E];
                to = new int[E];
                cap = new int[E];
                rev = new int[E];
                clear();
            }

            public void clear(int v) {
                m = 0;
                for(int i = 0; i < v; i++) {
                    head[i] = -1;
                }
            }

            public void clear() {
                m = 0;
                Arrays.fill(head, -1);
            }

            public void addEdge(int s, int t, int c, int r) {
                next[m] = head[s];
                head[s] = m;
                to[m] = t;
                cap[m] = c;
                rev[m++] = r;
            }
        }
    }



    final IOFast io = new IOFast();


