    static void solve() throws Exception {
        int n = nextInt();
        int a[] = new int[n];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
            ans = max(ans, a[i]);
        }
        for (int eat = 1; eat < ans; eat++) {
            int cans = eat;
            for (int i: a) {
                cans += (i - 1) / eat;
            }
            ans = min(ans, cans);
        }
