            int c = in.nextInt();
            if (r > c) {
                r ^= c;
                c ^= r;
                r ^= c;
            }
            boolean rich = true;
            if ((r * c) % n == 0) {
                if (n <= 2) {
                    rich = false;
                } else if (r > 1) {
                    if (n == 3) {
                        rich = false;
                    } else {
                        if (c == 4 && r > 2) {
                            rich = false;
                        }
                    }
                }
            }
            System.out.println("Case #" + t + ": " + (rich ? "RICHARD" : "GABRIEL"));
        }
    }

