 public static String check(String a)
 {
    for(int i=0;i<a.length()-1;i++)
    {
        if(a.charAt(i)>a.charAt(i+1))
        {
            String s = a.substring(0,i)+Character.toString((char) (a.charAt(i)-1));
            if (s.charAt(0)=='0')
            s="";
            for (int j=a.length()-1;j>i;j--)
            {
                s+="9";
            }
            return check(s);
        }
    }
    return a;
 }

