 class TaskB {
     public void solve(int testNumber, InputReader in, OutputWriter out) {
         out.printFormat("Case #%d: ", testNumber);
         int n = in.readInt();
         int m = in.readInt();
         int need = in.readInt();
         boolean[][] filled = new boolean[n][m];
         int min = Integer.MAX_VALUE;
         for (int mask = 0; mask < (1 << (n*m)); mask++) {
             if (Integer.bitCount(mask) != need) {
                 continue;
             }
             for (int i = 0; i < n; i++) {
                 for (int j = 0; j < m; j++) {
                     int bit = i*m + j;
                     if ((mask & (1 << bit)) != 0) {
                         filled[i][j] = true;
                     } else {
                         filled[i][j] = false;
                     }
                 }
             }
             int ans = 0;
             for (int x = 0; x < n; x++) {
                 for (int y = 0; y < m; y++) {
                     if (filled[x][y]) {
                         for (int i = 0; i < 4; i++) {
                             int nx = x + MiscUtils.DX4[i];
                             int ny = y + MiscUtils.DY4[i];
                             if (MiscUtils.isValidCell(nx, ny, n, m)) {
                                 if (filled[nx][ny]) {
                                     ans++;
                                 }
                             }
                         }
                     }
                 }
             }
             if (ans % 2 != 0) {
                 throw new RuntimeException();
             }
             min = Math.min(min, ans / 2);
         }
         out.printLine(min);
     }
 }

 class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c))
                res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public String next() {
        return readString();
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
 }

 class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void printFormat(String format, Object...objects) {
        writer.printf(format, objects);
    }

    public void close() {
        writer.close();
    }

    public void printLine(int i) {
        writer.println(i);
    }
 }

 class MiscUtils {
    public static final int[] DX4 = {1, 0, -1, 0};
    public static final int[] DY4 = {0, -1, 0, 1};

    public static boolean isValidCell(int row, int column, int rowCount, int columnCount) {
        return row >= 0 && row < rowCount && column >= 0 && column < columnCount;
    }

 }

