            boolean flag = false;
            for(int a=1;a<N;a++){
                double delta = 0;
                for(int b=0;b<a;b++){
                    delta += P[a]-P[b];
                }
                if(delta>U){
                    delta = U;
                    flag=true;
                }
                U-=delta;
                delta/=(a);
                for(int b=0;b<a;b++){
                    P[b]+=delta;
                }

                if(flag)break;
            }


            for(int a=0;a<N;a++){
                P[a]=Math.min(1.0, P[a] + (U/N));
            }

            double ans = 1;

            for(int a=0;a<N;a++){
                System.out.print(P[a]+" ");
                ans *= P[a];
            }
            System.out.println();

            System.out.printf("Case #%d: %.12f%n", t, ans);
