     long countWaysRet=0;
     void countWays_r(int[][] graph, int[] mark, int S) {
    if (countWaysRet == Long.MAX_VALUE) {
        return;
    }
    if (S == graph.length-1) {
        countWaysRet++;
        return;
    }
    mark[S]=1;
    for (int i=0; i<graph[S].length; i++) {
        if (i==S) {
        continue;
        }
        if (graph[S][i] != 0) {
        if (mark[i] == 1) {
            countWaysRet =  Long.MAX_VALUE;
            return;
        }
        countWays_r(graph, mark, i);
        }
    }
    mark[S]=0;
     }

     long countWays(int[][] graph) {
    int[] mark = new int[graph.length];
    Arrays.fill(mark,0);
    countWaysRet = 0;
    countWays_r(graph, mark, 0);
    return countWaysRet;
     }

     class FoundAnswer extends Exception {
    public FoundAnswer() {
    }
     }
     long solveSmall_r_M=-1;

     private void solveSmall_r(int[][] graph, int S1, int S2) throws FoundAnswer {
    int N = graph.length;
    long w1;

    graph[S1][S2]=1;

    if (S2 == N-1 && S1 == N-2) {
        w1 = countWays(graph);
        if (w1 == solveSmall_r_M) {
        throw new FoundAnswer();
        }
    } else {
        int nS1 = S1;
        int nS2 = S2+1;
        if (nS2 >= N) {
        nS1++;
        nS2 = nS1+1;
        }
        solveSmall_r(graph, nS1, nS2);
    }

    graph[S1][S2]=0;

    if (S2 == N-1 && S1 == N-2) {
        w1 = countWays(graph);
        if (w1 == solveSmall_r_M) {
        throw new FoundAnswer();
        }
    } else {
        int nS1 = S1;
        int nS2 = S2+1;
        if (nS2 >= N) {
        nS1++;
        nS2 = nS1+1;
        }
        solveSmall_r(graph, nS1, nS2);
    }
     }


     private void solve(int B, long M) {

    int[][] graph = new int[B][B];
    boolean ans1 = false;

    try {
        solveSmall_r_M = M;
        solveSmall_r(graph, 0, 1);
    } catch (FoundAnswer a) {
        ans1 = true;
    }

    if (ans1) {
        output(graph);
    } else {
        output(null);
    }

     }

