    if (solveRMaxSize == J*P*S) {
        throw new Exception();
    }

    boolean startFlag=false;
    for (int j=0 ;j<J; j++) {
        for (int p=0; p<P; p++) {
        for (int s=0; s<S; s++) {
            if (!startFlag) {
            j=ans.get(ans.size()-1).get(0).intValue();
            p=ans.get(ans.size()-1).get(1).intValue();
