public class Monkey implements Runnable {
   private static final String NAME = "monkey";

   private  StreamTokenizer in;

   int nextInt() throws Exception {
     in.nextToken();
     return (int) in.nval;
   }

   long nextLong() throws Exception {
     in.nextToken();
     return (long) in.nval;
