            int x = iread() - 1, y = iread() - 1, b = iread();
            field[x][y] = b;
            good[x][y] = 1;
        }
        int RC = Math.max(R, C);
        boolean flag = true;
        int tries = 0;
        while (flag) {
            tries++;
            if (tries>RC) {
                System.out.println("WTF");
            }
            flag = false;
            for (int x = 0; x < R; x++) {
                for (int y = 0; y < C; y++) {
                    if (x > 0 && field[x][y] > field[x - 1][y] + D) {
                        field[x][y] = field[x - 1][y] + D;
                        if (good[x][y] > 0) {
                            out.write("IMPOSSIBLE");
                            return;
                        }
                        flag = true;
                    }
                    if (x + 1 < R && field[x][y] > field[x + 1][y] + D) {
                        field[x][y] = field[x + 1][y] + D;
                        if (good[x][y] > 0) {
                            out.write("IMPOSSIBLE");
                            return;
                        }
                        flag = true;
                    }
                    if (y > 0 && field[x][y] > field[x][y - 1] + D) {
                        field[x][y] = field[x][y - 1] + D;
                        if (good[x][y] > 0) {
                            out.write("IMPOSSIBLE");
                            return;
                        }
                        flag = true;
                    }
                    if (y + 1 < C && field[x][y] > field[x][y + 1] + D) {
                        field[x][y] = field[x][y + 1] + D;
                        if (good[x][y] > 0) {
                            out.write("IMPOSSIBLE");
                            return;
                        }
                        flag = true;
                    }
                }
            }
        }

        long ans = 0;
        for (int x = 0; x < R; x++) {
            for (int y = 0; y < C; y++) {
                ans += field[x][y];
            }
        }
        ans %= 1000000007;
        out.write(ans + "");
    }

    public void solve_gcj() throws Exception {
        int tests = iread();
        for (int test = 1; test <= tests; test++) {
            out.write("Case #" + test + ": ");
            solve();
            out.write("\n");
        }
    }

    public void run() {
        try {


            in = new BufferedReader(new FileReader(filename + ".in"));
            out = new BufferedWriter(new FileWriter(filename + ".out"));
            solve_gcj();
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    public int iread() throws Exception {
        return Integer.parseInt(readword());
    }

    public double dread() throws Exception {
        return Double.parseDouble(readword());
    }

    public long lread() throws Exception {
        return Long.parseLong(readword());
    }

    BufferedReader in;

    BufferedWriter out;

    public String readword() throws IOException {
        StringBuilder b = new StringBuilder();
        int c;
        c = in.read();
        while (c >= 0 && c <= ' ')
            c = in.read();
        if (c < 0)
            return "";
        while (c > ' ') {
            b.append((char) c);
            c = in.read();
        }
        return b.toString();
    }

    public static void main(String[] args) {
        try {
            Locale.setDefault(Locale.US);
        } catch (Exception e) {

        }
        new Thread(new Main()).start();

    }
