     static class TaskC {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int n;
                 int k;
                 double u;
                 double[] p;


                 public void read(InputReader in) {
                     n = in.readInt();
                     k = in.readInt();
                     u = in.readDouble();
                     p = IOUtils.readDoubleArray(in, n);
                 }

                 double answer;


                 public void solve() {
                     Arrays.sort(p);
                     double sumSoFar = 0;
                     for (int i = 0; i < n; i++) {
                         sumSoFar += p[i];
                         double next = i == n - 1 ? 1 : p[i + 1];
                         if ((i + 1) * next - sumSoFar >= u || i == n - 1) {
                             double each = (sumSoFar + u) / (i + 1);
                             for (int j = 0; j <= i; j++) {
                                 p[j] = each;
                             }
                             break;
                         }
                     }
                     answer = 1;
                     for (double i : p) {
                         answer *= i;
                     }
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.printLine("Case #" + testNumber + ":", answer);
                 }
             }, 4);
         }

     }

