     static class Scheduler {
         private final AtomicInteger testsRemaining;
         private final AtomicInteger threadsRemaining;

         public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
             try {
                 testsRemaining = new AtomicInteger(in.readInt());
                 threadsRemaining = new AtomicInteger(numParallel);
                 Task[] tasks = new Task[testsRemaining.get()];
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i] = factory.newTask();
                 }
                 for (Task task : tasks) {
                     task.read(in);
                     new Thread(() -> {
                         boolean freeThread = false;
                         synchronized (this) {
                             do {
                                 try {
                                     wait(10);
                                 } catch (InterruptedException ignored) {
                                 }
                                 if (threadsRemaining.get() != 0) {
                                     synchronized (threadsRemaining) {
                                         if (threadsRemaining.get() != 0) {
                                             threadsRemaining.decrementAndGet();
                                             freeThread = true;
                                         }
                                     }
                                 }
                             } while (!freeThread);
                         }
                         task.solve();
                         System.err.println(testsRemaining.decrementAndGet());
                         threadsRemaining.incrementAndGet();
                     }).start();
                 }
                 synchronized (this) {
                     while (testsRemaining.get() > 0) {
                         wait(10);
                     }
                 }
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i].write(out, i + 1);
                 }
             } catch (InterruptedException e) {
                 throw new RuntimeException(e);
             }
         }

     }

     static class Range {
         public static IntList range(int from, int to) {
             int[] result = new int[Math.abs(from - to)];
             int current = from;
             if (from <= to) {
                 for (int i = 0; i < result.length; i++) {
                     result[i] = current++;
                 }
             } else {
                 for (int i = 0; i < result.length; i++) {
                     result[i] = current--;
                 }
             }
             return new IntArray(result);
         }

     }

     static class MiscUtils {
         public static void decreaseByOne(int[]... arrays) {
             for (int[] array : arrays) {
                 for (int i = 0; i < array.length; i++) {
                     array[i]--;
                 }
             }
         }

     }

     static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
         public IntIterator intIterator();

         default public Iterator<Integer> iterator() {
             return new Iterator<Integer>() {
                 private IntIterator it = intIterator();

                 public boolean hasNext() {
                     return it.isValid();
                 }

                 public Integer next() {
                     int result = it.value();
                     it.advance();
                     return result;
                 }
             };
         }

         default public int compareTo(IntStream c) {
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 int i = it.value();
                 int j = jt.value();
                 if (i < j) {
                     return -1;
                 } else if (i > j) {
                     return 1;
                 }
                 it.advance();
                 jt.advance();
             }
             if (it.isValid()) {
                 return 1;
             }
             if (jt.isValid()) {
                 return -1;
             }
             return 0;
         }

         default public int max() {
             int result = Integer.MIN_VALUE;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 int current = it.value();
                 if (current > result) {
                     result = current;
                 }
             }
             return result;
         }

         default public int[] qty(int bound) {
             int[] result = new int[bound];
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 result[(int) it.value()]++;
             }
             return result;
         }

     }

     static interface Task {
         public void read(InputReader in);

         public void solve();

         public void write(OutputWriter out, int testNumber);

     }

     static interface IntIterator {
         public int value() throws NoSuchElementException;

         public boolean advance();

         public boolean isValid();

     }

     static abstract class IntAbstractStream implements IntStream {

         public String toString() {
             StringBuilder builder = new StringBuilder();
             boolean first = true;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 if (first) {
                     first = false;
                 } else {
                     builder.append(' ');
                 }
                 builder.append(it.value());
             }
             return builder.toString();
         }


         public boolean equals(Object o) {
             if (!(o instanceof IntStream)) {
                 return false;
             }
             IntStream c = (IntStream) o;
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 if (it.value() != jt.value()) {
                     return false;
                 }
                 it.advance();
                 jt.advance();
             }
             return !it.isValid() && !jt.isValid();
         }


         public int hashCode() {
             int result = 0;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 result *= 31;
                 result += it.value();
             }
             return result;
         }

     }

     static class OutputWriter {
         private final PrintWriter writer;

         public OutputWriter(OutputStream outputStream) {
             writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
         }

         public OutputWriter(Writer writer) {
             this.writer = new PrintWriter(writer);
         }

         public void print(Object... objects) {
             for (int i = 0; i < objects.length; i++) {
                 if (i != 0) {
                     writer.print(' ');
                 }
                 writer.print(objects[i]);
             }
         }

         public void printLine(Object... objects) {
             print(objects);
             writer.println();
         }

         public void close() {
             writer.close();
         }

     }

     static interface IntComparator {
         public int compare(int first, int second);

     }

     static interface TaskFactory {
         public Task newTask();

     }
 }

