public class A {
    int n;
    int[] a;

    String solve() {
        int ans1 = 0;
        int rate = 0;
        for (int i = 1; i < n; i++) {
            if (a[i - 1] > a[i]) {
                ans1 += a[i - 1] - a[i];
                rate = Math.max(rate, a[i - 1] - a[i]);
            }
        }
        int ans2 = 0;
        for (int i = 1; i < n; i++) {
            ans2 += Math.min(rate, a[i - 1]);
        }
        return ans1 + " " + ans2;
    }

    public A(Scanner in) {
        n = in.nextInt();
        a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
    }

