public class C {
    int m;
    String[] s;

    String solve() {
        TreeMap<String, Integer> words = new TreeMap<>();
        int[][] ids = new int[m][];
        for (int i = 0; i < m; i++) {
            TreeSet<Integer> set = new TreeSet<>();
            for (String w : s[i].split("\\s+")) {
                if (!words.containsKey(w)) {
                    words.put(w, words.size());
                }
                set.add(words.get(w));
            }
            ids[i] = new int[set.size()];
            int k = 0;
            for (int x : set) {
                ids[i][k++] = x;
            }
        }
        int wordsCount = words.size();
        int[] which = new int[wordsCount];
        int ans = Integer.MAX_VALUE;
        for (int mask = 0; mask < (1 << m); mask++) {
            if ((mask & 3) != 1) {
                continue;
            }
            Arrays.fill(which, 0);
            for (int i = 0; i < m; i++) {
                int lang = ((mask & (1 << i)) != 0) ? 1 : 2;
                for (int id : ids[i]) {
                    which[id] |= lang;
                }
            }
            int common = 0;
            for (int i = 0; i < wordsCount; i++) {
                if (which[i] == 3) {
                    common++;
                }
            }
            ans = Math.min(ans, common);
        }
        return "" + ans;
    }

    public C(Scanner in) {
        m = in.nextInt();
        in.nextLine();
        s = new String[m];
        for (int i = 0; i < m; i++) {
            s[i] = in.nextLine();
        }
    }

    public static void main(String[] args) throws Exception {
        int nThreads = 4;
        String fileNameSuffix = "";
        String formatOut = "Case #%2$d: %1$s";
        String formatSystemOut = formatOut;

